```ts
const HARNESS_SHUTDOWN_TIMEOUT_MS = 30_000;

async function withDeadline<T>(
  operation: Promise<T>,
  timeoutMs: number,
  description: string,
): Promise<T> {
  const signal = AbortSignal.timeout(timeoutMs);
  return await Promise.race([
    operation,
    new Promise<never>((_resolve, reject) => {
      signal.addEventListener(
        "abort",
        () => reject(new Error(`${description} timed out after ${String(timeoutMs)}ms`)),
        { once: true },
      );
    }),
  ]);
}

async function stopChrome(
  browser: Browser | null,
  chromeProcess: ServiceProcess | null,
  chromeExited: Promise<unknown[]> | null,
): Promise<void> {
  if (chromeProcess === null) return;

  if (
    browser?.isConnected() &&
    chromeProcess.exitCode === null &&
    chromeProcess.signalCode === null
  ) {
    try {
      const session = await browser.newBrowserCDPSession();
      await session.send("Browser.close");

      if (chromeExited !== null) {
        await withDeadline(
          chromeExited,
          HARNESS_SHUTDOWN_TIMEOUT_MS,
          "Chrome process exit after Browser.close",
        );
      }
      return;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      trace(`graceful Chrome close failed: ${message}`);
    }
  }

  if (chromeProcess.exitCode === null && chromeProcess.signalCode === null) {
    await stopProcess(chromeProcess);
  }

  if (chromeExited !== null) {
    await withDeadline(chromeExited, HARNESS_SHUTDOWN_TIMEOUT_MS, "Chrome process exit");
  }
}
```

This still forcibly removes the Windows process tree when graceful shutdown fails, but never blindly terminates Chrome twice.

