Wrap the scenario so cleanup errors are accumulated. If the scenario failed, its original error remains authoritative; if it succeeded, cleanup failures remain visible as an `AggregateError`:

```ts
let scenarioFailed = false;

try {
  // Existing scenario body, unchanged.
} catch (error) {
  scenarioFailed = true;
  throw error;
} finally {
  trace("cleanup-start");
  const cleanupErrors: Error[] = [];

  const cleanup = async (
    description: string,
    operation: () => void | Promise<void>,
  ): Promise<void> => {
    try {
      await operation();
    } catch (error) {
      const cleanupError = new Error(`${description}: ${errorMessage(error)}`, {
        cause: error,
      });
      cleanupErrors.push(cleanupError);
      trace(`cleanup-error:${cleanupError.message}`);
    }
  };

  await cleanup("close Chrome through CDP", async () => {
    const activeBrowser = browser;
    if (activeBrowser?.isConnected()) {
      const session = await activeBrowser.newBrowserCDPSession();
      await session.send("Browser.close");
    }
  });

  await cleanup("await graceful Chrome exit", async () => {
    if (
      chromeProcess !== null &&
      chromeProcess.exitCode === null &&
      chromeProcess.signalCode === null
    ) {
      await waitForExit(chromeProcess);
    }
  });

  await cleanup("force remaining Chrome process tree", async () => {
    if (
      chromeProcess !== null &&
      chromeProcess.exitCode === null &&
      chromeProcess.signalCode === null
    ) {
      await stopProcess(chromeProcess);
    }
  });

  for (const child of processes.toReversed()) {
    await cleanup("stop service process", () => stopProcess(child));
  }

  await cleanup("remove Chrome profile", () =>
    rmSync(profilePath, { force: true, recursive: true }),
  );
  await cleanup("remove private snapshot", () =>
    rmSync(privateSnapshotPath, { force: true }),
  );
  await cleanup("remove projection database", () =>
    rmSync(projectionDatabasePath, { force: true }),
  );

  if (!scenarioFailed && cleanupErrors.length > 0) {
    throw new AggregateError(cleanupErrors, "prepared-evidence cleanup failed");
  }
