function trace(message: string): void {
  if (process.env.DEBUG_WP3_E2E === "true") console.log(`[wp3-e2e] ${message}`);
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function withTimeout<T>(
  operation: Promise<T>,
  timeoutMs: number,
  description: string,
): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_resolve, reject) => {
    timer = setTimeout(() => reject(new Error(`${description} timeout`)), timeoutMs);
  });
  try {
    return await Promise.race([operation, timeout]);
  } finally {
    if (timer !== undefined) clearTimeout(timer);
  }
}

async function waitForExit(child: ChildProcess, description: string): Promise<void> {
  if (child.exitCode !== null || child.signalCode !== null) return;
  await withTimeout(
    once(child, "exit").then(() => undefined),
    HARNESS_SHUTDOWN_TIMEOUT_MS,
    description,
  );
}

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

async function waitForOutput(
  stream: Readable,
  expected: string,
  timeoutMs = HARNESS_STARTUP_TIMEOUT_MS,
): Promise<void> {
  await new Promise<void>((resolve, reject) => {
    let output = "";
    const signal = AbortSignal.timeout(timeoutMs);
    const cleanup = () => {
      stream.off("data", onData);
      stream.off("end", onEnd);
      signal.removeEventListener("abort", onAbort);
    };
    const onData = (chunk: Buffer) => {
      output += chunk.toString("utf8");
      if (output.includes(expected)) {
        cleanup();
        resolve();
      }
    };
    const onEnd = () => {
      cleanup();
      reject(new Error(`process exited before emitting ${expected}: ${output}`));
    };
    const onAbort = () => {
      cleanup();
      reject(new Error(`process did not emit ${expected}: ${output}`));
    };
    stream.on("data", onData);
    stream.once("end", onEnd);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

async function startProcess(
  command: readonly string[],
  environment: Record<string, string>,
  expectedOutput: string,
  cwd?: string,
  output: "stdout" | "stderr" = "stdout",
): Promise<ServiceProcess> {
  const executable = command[0];
  if (executable === undefined) throw new Error("empty process command");
  const process = spawn(executable, command.slice(1), {
    ...(cwd === undefined ? {} : { cwd }),
    env: { ...globalThis.process.env, ...environment },
    stdio: ["ignore", "pipe", "pipe"],
  });
  const readinessStream = output === "stdout" ? process.stdout : process.stderr;
  const backgroundStream = output === "stdout" ? process.stderr : process.stdout;
  backgroundStream.resume();
  try {
    await waitForOutput(readinessStream, expectedOutput);
    readinessStream.resume();
    return process;
  } catch (error) {
    readinessStream.resume();
    try {
      await stopProcess(process);
    } catch (cleanupError) {
      trace(`startup-cleanup-error:${errorMessage(cleanupError)}`);
    }
    throw error;
  }
}

