  const executable = command[0];
  if (executable === undefined) throw new Error("empty command");
  const child = spawn(executable, command.slice(1), {
    ...(cwd === undefined ? {} : { cwd }),
    env: globalThis.process.env,
    stdio: ["ignore", "pipe", "pipe"],
